Entendido. Para crear un sketch de p5.js de una flor, seguiré las reglas: crearé los tres archivos necesarios (`index.html`, `style.css`, y `script.js`) y me aseguraré de que el canvas sea de pantalla completa.

Aquí están las llamadas para crear la estructura y el código.

// 1. Crear index.html
[CALL:write_file]{"path": "index.html", "content": "<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Flor p5.js</title>
    <link rel="stylesheet" href="style.css">
    <script src="https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.4.0/p5.js"></script>
    <script src="script.js"></script>
</head>
<body>
    <!-- El canvas se creará y se ajustará en style.css -->
</body>
</html>"}

// 2. Crear style.css para fullscreen
[CALL:write_file]{"path": "style.css", "content": "body { margin: 0; padding: 0; overflow: hidden; }
canvas { display: block; width: 100vw; height: 100vh; }"}

// 3. Crear script.js con la lógica de la flor
[CALL:write_file]{"path": "script.js", "content": "// Función setup: se ejecuta una vez
function setup() {
    // Creamos el canvas para que ocupe toda la ventana
    createCanvas(windowWidth, windowHeight);
    angleMode(DEGREES);
}

// Función draw: se ejecuta en cada frame
function draw() {
    background(220, 240, 255); // Fondo azul muy claro
    translate(width / 2, height / 2); // Centrar el origen
    scale(0.8); // Escalar ligeramente para que no quede demasiado grande

    // --- Tallo y hojas (Verde) ---
    stroke(50, 150, 50); // Verde oscuro para el borde
    strokeWeight(3);
    line(0, 0, 0, height * 0.6); // Tallo principal

    // Hojas simples
    fill(50, 180, 50, 150); // Verde semi-transparente
    noStroke();
    ellipse(-50, -50, 80, 30);
    ellipse(50, -30, 70, 35);

    // --- Pétalos de la Flor (Interpolación de color) ---
    // Usaremos un bucle para dibujar pétalos con un gradiente de color (Rojo a Azul)
    let numPetals = 12;
    let petalRadius = 80;
    let petalSpacing = 30;

    for (let i = 0; i < numPetals; i++) {
        push();
        rotate(i * (360 / numPetals));

        // Calcular el color interpolado: Rojo (0, 0, 255) a Azul (255, 0, 0) en el índice i
        // Queremos que el color cambie de Rojo (0, 0, 255) a Azul (255, 0, 0) a medida que i aumenta.
        // Rojo puro: (255, 0, 0) -> Azul puro: (0, 0, 255)
        // Interpolación de R: 255 -> 0 (R = 255 * (1 - i/numPetals))
        // Interpolación de G: 0 -> 0 (G = 0)
        // Interpolación de B: 0 -> 255 (B = 255 * (i/numPetals))

        let r = map(i, 0, numPetals - 1, 255, 0); // Rojo va de 255 a 0
        let g = 0; // Verde siempre 0
        let b = map(i, 0, numPetals - 1, 0, 255); // Azul va de 0 a 255

        // Usamos un color que va de Rojo (i=0) a Azul (i=numPetals-1)
        fill(r, g, b, 200); 
        stroke(r, g, b); // Borde del pétalo con el mismo color
        strokeWeight(2);

        // Dibujar el pétalo como un óvalo ligeramente curvado
        ellipse(0, 0, petalRadius, petalRadius * 1.2);

        pop();
    }

    // --- Centro de la Flor (Amarillo/Naranja) ---
    fill(255, 165, 0); // Naranja
    noStroke();
    ellipse(0, 0, 60, 60);
}

// Manejar el redimensionamiento de la ventana
function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
}
"}

// 4. Prueba de conexión
[CALL:execute_js]{"code": "console.log('MCP OK')"}
